import { describe, it, expect } from "vitest";
import { createChaseCamera } from "./chase-camera.ts";

const eye = { x: 1, y: 2, z: -5 };
const target = { x: 0, y: 1, z: 3 };
const norm = (v: any) => { const l = Math.hypot(v.x, v.y, v.z); return { x: v.x / l, y: v.y / l, z: v.z / l }; };
const dot = (a: any, b: any) => a.x * b.x + a.y * b.y + a.z * b.z;
const cross = (a: any, b: any) => ({ x: a.y * b.z - a.z * b.y, y: a.z * b.x - a.x * b.z, z: a.x * b.y - a.y * b.x });
const col = (m: any, i: number) => ({ x: m[4 * i], y: m[4 * i + 1], z: m[4 * i + 2] });
const fwd = norm({ x: target.x - eye.x, y: target.y - eye.y, z: target.z - eye.z });

describe("chase camera", () => {
    it("starts upright and looks at the target", () => {
        const c = createChaseCamera(eye, target);
        const m = c.camera.worldMatrix as any;
        expect(m[12]).toBeCloseTo(eye.x); expect(m[13]).toBeCloseTo(eye.y); expect(m[14]).toBeCloseTo(eye.z);
        const z = col(m, 2);
        expect(dot(z, fwd)).toBeCloseTo(1, 9);
        // picture up is the world up projected perpendicular to the view
        const p = norm({ x: 0 - dot({x:0,y:1,z:0}, fwd) * fwd.x, y: 1 - fwd.y * fwd.y, z: 0 - dot({x:0,y:1,z:0}, fwd) * fwd.z });
        expect(dot(col(m, 1), p)).toBeCloseTo(1, 9);
    });

    it("rolls so picture-up matches the given up's perpendicular component", () => {
        const c = createChaseCamera(eye, target);
        const up = norm({ x: 0.6, y: 0.3, z: -0.7 });
        c.bank(up);
        const m = c.camera.worldMatrix as any;
        const y = col(m, 1);
        const expected = norm({ x: up.x - dot(up, fwd) * fwd.x, y: up.y - dot(up, fwd) * fwd.y, z: up.z - dot(up, fwd) * fwd.z });
        expect(dot(y, expected)).toBeCloseTo(1, 9);
        expect(dot(col(m, 2), fwd)).toBeCloseTo(1, 9);
        // right-handed basis preserved
        const x = col(m, 0);
        const cr = cross(x, y);
        expect(dot(cr, col(m, 2))).toBeCloseTo(1, 9);
    });

    it("keeps previous roll when up is exactly along the line of sight, either way", () => {
        const c = createChaseCamera(eye, target);
        const up = norm({ x: 0.6, y: 0.3, z: -0.7 });
        c.bank(up);
        const before = Array.from(c.camera.worldMatrix as any) as number[];
        c.bank(fwd);
        expect(Array.from(c.camera.worldMatrix as any)).toEqual(before);
        c.bank({ x: -fwd.x, y: -fwd.y, z: -fwd.z });
        expect(Array.from(c.camera.worldMatrix as any)).toEqual(before);
        expect(dot(col(c.camera.worldMatrix as any, 2), fwd)).toBeCloseTo(1, 9);
    });

    it("keeps previous roll on degenerate up at start, too", () => {
        const c = createChaseCamera(eye, target);
        const before = Array.from(c.camera.worldMatrix as any) as number[];
        c.bank(fwd);
        expect(Array.from(c.camera.worldMatrix as any)).toEqual(before);
    });

    it("handles a 180-degree roll (up flipped perpendicular)", () => {
        const c = createChaseCamera(eye, target);
        const p = norm({ x: 0, y: 1, z: 0 });
        c.bank({ x: -p.x, y: -p.y, z: -p.z });
        const y = col(c.camera.worldMatrix as any, 1);
        expect(dot(y, { x: -p.x + dot(p, fwd) * fwd.x, y: -p.y + dot(p, fwd) * fwd.y, z: -p.z + dot(p, fwd) * fwd.z })).toBeGreaterThan(0.999999);
    });
});
